//   docs/music-catalog-simplified-report.md
//   docs/music-catalog-simplified-report.json
// Detailed (pre-simplification) evidence and per-tag reasoning:
//   docs/music-catalog-genre-migration-report.md
//   docs/music-catalog-genre-migration-report.json
// ============================================================================

export type Genre =
  | "pop"
  | "rock"
  | "hip-hop"
  | "rnb-soul"
  | "jazz-funk"
  | "electronic"
  | "folk-acoustic"
  | "ambient-dream";

export type SimplifiedCanonicalTrackDraft = {
  id: string;
  title: string;
  artist: string;

  genre: Genre;

  energy: "low" | "medium" | "high";

  tags: string[];

  alternateVideoIds: string[];

  legacy: {
    sourceEntries: Array<{
      sourceArray: string;
      laneId: string;
      title: string;
      artist: string;
      youtubeVideoId: string;
      energy: "low" | "medium" | "high";
      moodTags: string[];
      sceneTags: string[];
      subTags: string[];
    }>;
  };

  review: {
    genreConfidence: number;
    needsGenreReview: boolean;
    needsDedupReview: boolean;
    needsMetadataReview: boolean;
    notes: string[];
  };
};


